1	package com.example.starter.observation;
2	
3	import com.fasterxml.jackson.core.JsonProcessingException;
4	import com.fasterxml.jackson.databind.ObjectMapper;
5	import org.springframework.dao.DuplicateKeyException;
6	import org.springframework.http.HttpStatus;
7	import org.springframework.stereotype.Service;
8	import org.springframework.transaction.annotation.Transactional;
9	
10	import java.math.BigDecimal;
11	import java.nio.charset.StandardCharsets;
12	import java.security.MessageDigest;
13	import java.security.NoSuchAlgorithmException;
14	import java.time.Clock;
15	import java.time.Instant;
16	import java.util.ArrayList;
17	import java.util.HexFormat;
18	import java.util.LinkedHashMap;
19	import java.util.List;
20	import java.util.Map;
21	import java.util.Objects;
22	import java.util.Optional;
23	import java.util.Set;
24	
25	/**
26	 * 现场观测离线三方合并业务服务。
27	 *
28	 * <p>写操作（创建/离线提交/删除）均在单事务内完成：先占位写入幂等去重记录，
29	 * 再对 observation_current 行加锁（SELECT ... FOR UPDATE）完成业务判定与变更，
30	 * 最后回填去重记录的响应并整体提交；任何业务失败都会回滚，去重记录不占键。
31	 *
32	 * <p>合并规则（按字段比较基线 base、当前 current、候选 candidate）：
33	 * 候选未改（等于基线）保留当前；当前未改接受候选；两边改为相同值也接受；
34	 * 否则整次 409，不写入任何部分结果。读数按数值比较，其余字段按原文比较。
35	 *
36	 * <p>显式冲突解决（RESOLVE）在同一套占位与行锁机制内执行：事务内重读基线与最新当前版本重算冲突，
37	 * 人工选择必须恰好覆盖重算后的冲突字段；成功后原子写入新观测版本（内容无变化则不加版本）、
38	 * 不可变 conflict_resolution 记录与 request_log 响应。resolutionId 全局唯一，同参重放、改参 409。
39	 */
40	@Service
41	public class ObservationService {
42	
43	    private static final String SEPARATOR = "\u0001";
44	
45	    /**
46	     * 三个可编辑字段的固定顺序：冲突重算、选择校验与指纹均以此顺序处理，保证结果稳定。
47	     */
48	    private static final List<String> FIELDS = List.of("location", "reading", "note");
49	
50	    private final ObservationRepository observationRepository;
51	    private final RequestLogRepository requestLogRepository;
52	    private final ResolutionRepository resolutionRepository;
53	    private final ObjectMapper objectMapper;
54	    private final Clock clock;
55	
56	    public ObservationService(ObservationRepository observationRepository,
57	                              RequestLogRepository requestLogRepository,
58	                              ResolutionRepository resolutionRepository,
59	                              ObjectMapper objectMapper,
60	                              Clock clock) {
61	        this.observationRepository = observationRepository;
62	        this.requestLogRepository = requestLogRepository;
63	        this.resolutionRepository = resolutionRepository;
64	        this.objectMapper = objectMapper;
65	        this.clock = clock;
66	    }
67	
68	    /**
69	     * 创建观测记录，初始版本为 1。记录已存在返回 409。
70	     */
71	    @Transactional
72	    public WriteOutcome create(CreateObservationRequest request) {
73	        String fingerprint = fingerprint("CREATE", request.observationId(), request.location(),
74	                request.reading(), request.note());
75	        WriteOutcome replayed = checkReplay(request.requestId(), fingerprint);
76	        if (replayed != null) {
77	            return replayed;
78	        }
79	        WriteOutcome concurrent = insertPlaceholder(request.requestId(), fingerprint, "CREATE");
80	        if (concurrent != null) {
81	            return concurrent;
82	        }
83	
84	        if (observationRepository.findCurrentForUpdate(request.observationId()).isPresent()) {
85	            throw ApiException.conflict("observation already exists: " + request.observationId(), null);
86	        }
87	        ObservationSnapshot snapshot = new ObservationSnapshot(request.observationId(), 1,
88	                request.location(), request.reading(), request.note(), false);
89	        try {
90	            observationRepository.insertCurrent(snapshot);
91	        } catch (DuplicateKeyException e) {
92	            // 并发创建同一 observationId：由主键串行化，后到者按冲突处理
93	            throw ApiException.conflict("observation already exists: " + request.observationId(), null);
94	        }
95	        observationRepository.insertVersion(snapshot);
96	        return complete(request.requestId(), HttpStatus.CREATED, ObservationResponse.of(snapshot));
97	    }
98	
99	    /**
100	     * 离线提交：基于 baseVersion 的三方合并。合并结果与当前完全相同则不加版本，否则版本加一。
101	     */
102	    @Transactional
103	    public WriteOutcome merge(String observationId, MergeObservationRequest request) {
104	        String fingerprint = fingerprint("MERGE", observationId, String.valueOf(request.baseVersion()),
105	                request.location(), request.reading(), request.note());
106	        WriteOutcome replayed = checkReplay(request.requestId(), fingerprint);
107	        if (replayed != null) {
108	            return replayed;
109	        }
110	        WriteOutcome concurrent = insertPlaceholder(request.requestId(), fingerprint, "MERGE");
111	        if (concurrent != null) {
112	            return concurrent;
113	        }
114	
115	        ObservationSnapshot current = observationRepository.findCurrentForUpdate(observationId)
116	                .orElseThrow(() -> ApiException.notFound("observation not found: " + observationId));
117	        if (current.deleted()) {
118	            throw ApiException.gone("observation already deleted: " + observationId);
119	        }
120	        ObservationSnapshot base = observationRepository.findVersion(observationId, request.baseVersion())
121	                .orElseThrow(() -> ApiException.notFound(
122	                        "base version not found: " + observationId + "@" + request.baseVersion()));
123	
124	        List<String> conflictFields = new ArrayList<>();
125	        String mergedLocation = mergeField("location", base.location(), current.location(),
126	                request.location(), conflictFields);
127	        String mergedReading = mergeReadingField(base.reading(), current.reading(),
128	                request.reading(), conflictFields);
129	        String mergedNote = mergeField("note", base.note(), current.note(), request.note(), conflictFields);
130	        if (!conflictFields.isEmpty()) {
131	            throw ApiException.mergeConflict(conflictFields, current.version());
132	        }
133	
134	        ObservationSnapshot merged = new ObservationSnapshot(observationId, current.version(),
135	                mergedLocation, mergedReading, mergedNote, false);
136	        if (sameContent(merged, current)) {
137	            // 合并结果与当前完全相同：返回当前版本，不加版本
138	            return complete(request.requestId(), HttpStatus.OK, ObservationResponse.of(current));
139	        }
140	        ObservationSnapshot next = new ObservationSnapshot(observationId, current.version() + 1,
141	                mergedLocation, mergedReading, mergedNote, false);
142	        observationRepository.updateCurrent(next);
143	        observationRepository.insertVersion(next);
144	        return complete(request.requestId(), HttpStatus.OK, ObservationResponse.of(next));
145	    }
146	
147	    /**
148	     * 删除观测记录：expectedVersion 匹配当前版本时生成新版本墓碑；已删除记录返回 410。
149	     */
150	    @Transactional
151	    public WriteOutcome delete(String observationId, DeleteObservationRequest request) {
152	        String fingerprint = fingerprint("DELETE", observationId, String.valueOf(request.expectedVersion()));
153	        WriteOutcome replayed = checkReplay(request.requestId(), fingerprint);
154	        if (replayed != null) {
155	            return replayed;
156	        }
157	        WriteOutcome concurrent = insertPlaceholder(request.requestId(), fingerprint, "DELETE");
158	        if (concurrent != null) {
159	            return concurrent;
160	        }
161	
162	        ObservationSnapshot current = observationRepository.findCurrentForUpdate(observationId)
163	                .orElseThrow(() -> ApiException.notFound("observation not found: " + observationId));
164	        if (current.deleted()) {
165	            throw ApiException.gone("observation already deleted: " + observationId);
166	        }
167	        if (request.expectedVersion() != current.version()) {
168	            throw ApiException.conflict("expectedVersion mismatch", current.version());
169	        }
170	        ObservationSnapshot tombstone = new ObservationSnapshot(observationId, current.version() + 1,
171	                null, null, null, true);
172	        observationRepository.markDeleted(observationId, tombstone.version());
173	        observationRepository.insertVersion(tombstone);
174	        return complete(request.requestId(), HttpStatus.OK, ObservationResponse.of(tombstone));
175	    }
176	
177	    /**
178	     * 查询当前内容；墓碑只返回删除状态和版本。
179	     */
180	    @Transactional(readOnly = true)
181	    public ObservationResponse getCurrent(String observationId) {
182	        ObservationSnapshot current = observationRepository.findCurrent(observationId)
183	                .orElseThrow(() -> ApiException.notFound("observation not found: " + observationId));
184	        return ObservationResponse.of(current);
185	    }
186	
187	    /**
188	     * 显式冲突解决：事务内重读基线与最新当前版本并按原三方规则重算冲突，不信任客户端上次看到的冲突列表。
189	     * 选择恰好覆盖本次仍冲突字段时生成新版本（内容无变化则不加版本）并原子写入不可变解决记录。
190	     */
191	    @Transactional
192	    public ResolveOutcome resolveConflict(String observationId, ResolveConflictRequest request) {
193	        Map<String, FieldSelection> selections = parseSelections(request.selections());
194	        String normalizedSelections = writeSelectionsJson(selections);
195	        String fingerprint = fingerprint("RESOLVE", observationId, request.resolutionId(),
196	                String.valueOf(request.baseVersion()), String.valueOf(request.expectedCurrentVersion()),
197	                request.location(), request.reading(), request.note(), normalizedSelections, request.operator());
198	        ResolveOutcome replayed = checkResolveReplay(request.requestId(), fingerprint);
199	        if (replayed != null) {
200	            return replayed;
201	        }
202	        ResolveOutcome concurrent = insertResolvePlaceholder(request.requestId(), fingerprint);
203	        if (concurrent != null) {
204	            return concurrent;
205	        }
206	
207	        ObservationSnapshot current = observationRepository.findCurrentForUpdate(observationId)
208	                .orElseThrow(() -> ApiException.notFound("observation not found: " + observationId));
209	
210	        // resolutionId 重放判定先于墓碑与版本校验：同参重放始终返回原结果（即使记录之后已被删除）；
211	        // 改参或跨记录复用一律 409。
212	        ResolutionRecord existing = resolutionRepository.findByResolutionId(request.resolutionId()).orElse(null);
213	        if (existing != null) {
214	            if (!sameResolutionParams(existing, observationId, request, normalizedSelections)) {
215	                throw ApiException.conflict(
216	                        "resolutionId reused with different parameters: " + request.resolutionId(),
217	                        current.version());
218	            }
219	            return completeResolve(request.requestId(), HttpStatus.OK, resolutionResponseOf(existing));
220	        }
221	
222	        if (current.deleted()) {
223	            throw ApiException.gone("observation already deleted: " + observationId);
224	        }
225	
226	        if (request.expectedCurrentVersion() != current.version()) {
227	            throw ApiException.conflict("expectedCurrentVersion mismatch", current.version());
228	        }
229	        ObservationSnapshot base = observationRepository.findVersion(observationId, request.baseVersion())
230	                .orElseThrow(() -> ApiException.notFound(
231	                        "base version not found: " + observationId + "@" + request.baseVersion()));
232	
233	        List<String> conflictFields = new ArrayList<>();
234	        boolean locationConflict = fieldConflicts(base.location(), current.location(), request.location(), false);
235	        if (locationConflict) {
236	            conflictFields.add("location");
237	        }
238	        boolean readingConflict = fieldConflicts(base.reading(), current.reading(), request.reading(), true);
239	        if (readingConflict) {
240	            conflictFields.add("reading");
241	        }
242	        boolean noteConflict = fieldConflicts(base.note(), current.note(), request.note(), false);
243	        if (noteConflict) {
244	            conflictFields.add("note");
245	        }
246	        validateSelectionCoverage(selections.keySet(), conflictFields);
247	
248	        String resolvedLocation = resolveFieldValue(locationConflict, selections.get("location"),
249	                base.location(), current.location(), request.location(), false);
250	        String resolvedReading = resolveFieldValue(readingConflict, selections.get("reading"),
251	                base.reading(), current.reading(), request.reading(), true);
252	        String resolvedNote = resolveFieldValue(noteConflict, selections.get("note"),
253	                base.note(), current.note(), request.note(), false);
254	
255	        ObservationSnapshot merged = new ObservationSnapshot(observationId, current.version(),
256	                resolvedLocation, resolvedReading, resolvedNote, false);
257	        boolean contentChanged = !sameContent(merged, current);
258	        int newVersion = contentChanged ? current.version() + 1 : current.version();
259	        if (contentChanged) {
260	            ObservationSnapshot next = new ObservationSnapshot(observationId, newVersion,
261	                    resolvedLocation, resolvedReading, resolvedNote, false);
262	            observationRepository.updateCurrent(next);
263	            observationRepository.insertVersion(next);
264	        }
265	
266	        ResolutionRecord record = new ResolutionRecord(
267	                request.resolutionId(), observationId, request.requestId(),
268	                request.baseVersion(), current.version(), newVersion,
269	                request.location(), request.reading(), request.note(),
270	                List.copyOf(conflictFields), normalizedSelections, request.operator(),
271	                Instant.now(clock), contentChanged);
272	        try {
273	            resolutionRepository.insert(record);
274	        } catch (DuplicateKeyException e) {
275	            // 并发下 resolutionId 已被其他事务占用（可能指向其他观测记录）：重读后同参重放，否则 409。
276	            ResolutionRecord winner = resolutionRepository.findByResolutionId(request.resolutionId())
277	                    .orElseThrow(() -> ApiException.conflict(
278	                            "resolutionId conflict: " + request.resolutionId(), current.version()));
279	            if (!sameResolutionParams(winner, observationId, request, normalizedSelections)) {
280	                throw ApiException.conflict(
281	                        "resolutionId reused with different parameters: " + request.resolutionId(),
282	                        current.version());
283	            }
284	            return completeResolve(request.requestId(), HttpStatus.OK, resolutionResponseOf(winner));
285	        }
286	
287	        ObservationSnapshot pointed = contentChanged
288	                ? new ObservationSnapshot(observationId, newVersion, resolvedLocation, resolvedReading, resolvedNote, false)
289	                : current;
290	        return completeResolve(request.requestId(), HttpStatus.OK,
291	                ResolutionResponse.of(record, pointed, objectMapper));
292	    }
293	
294	    /**
295	     * 按全局唯一 resolutionId 查询不可变解决记录；不存在返回 404。
296	     */
297	    @Transactional(readOnly = true)
298	    public ResolutionRecord getResolution(String resolutionId) {
299	        return resolutionRepository.findByResolutionId(resolutionId)
300	                .orElseThrow(() -> ApiException.notFound("resolution not found: " + resolutionId));
301	    }
302	
303	    /**
304	     * 按 observationId 查询解决历史，按解决时刻先后排序；观测记录不存在返回 404。
305	     */
306	    @Transactional(readOnly = true)
307	    public List<ResolutionRecord> listResolutions(String observationId) {
308	        observationRepository.findCurrent(observationId)
309	                .orElseThrow(() -> ApiException.notFound("observation not found: " + observationId));
310	        return resolutionRepository.findByObservationId(observationId);
311	    }
312	
313	    /**
314	     * 读取指定历史版本快照（供解决记录响应组装使用）；不存在返回 404。
315	     */
316	    @Transactional(readOnly = true)
317	    public ObservationSnapshot getVersionSnapshot(String observationId, int version) {
318	        return observationRepository.findVersion(observationId, version)
319	                .orElseThrow(() -> ApiException.notFound(
320	                        "version not found: " + observationId + "@" + version));
321	    }
322	
323	    /**
324	     * 查询指定历史版本；墓碑版本只返回删除状态和版本。
325	     */
326	    @Transactional(readOnly = true)
327	    public ObservationResponse getVersion(String observationId, int version) {
328	        ObservationSnapshot snapshot = observationRepository.findVersion(observationId, version)
329	                .orElseThrow(() -> ApiException.notFound(
330	                        "version not found: " + observationId + "@" + version));
331	        return ObservationResponse.of(snapshot);
332	    }
333	
334	    /**
335	     * 普通字段三方合并：候选未改保留当前；当前未改接受候选；两边改为相同值接受；否则记录冲突。
336	     */
337	    private String mergeField(String field, String base, String current, String candidate,
338	                              List<String> conflictFields) {
339	        if (Objects.equals(candidate, base)) {
340	            return current;
341	        }
342	        if (Objects.equals(current, base) || Objects.equals(candidate, current)) {
343	            return candidate;
344	        }
345	        conflictFields.add(field);
346	        return current;
347	    }
348	
349	    /**
350	     * 读数字段三方合并：按数值比较（BigDecimal），其余规则与普通字段一致。
351	     */
352	    private String mergeReadingField(String base, String current, String candidate,
353	                                     List<String> conflictFields) {
354	        if (readingEquals(candidate, base)) {
355	            return current;
356	        }
357	        if (readingEquals(current, base) || readingEquals(candidate, current)) {
358	            return candidate;
359	        }
360	        conflictFields.add("reading");
361	        return current;
362	    }
363	
364	    /**
365	     * 判断合并结果与当前版本内容是否完全相同（读数按数值，其余按原文）。
366	     */
367	    private boolean sameContent(ObservationSnapshot merged, ObservationSnapshot current) {
368	        return Objects.equals(merged.location(), current.location())
369	                && Objects.equals(merged.note(), current.note())
370	                && readingEquals(merged.reading(), current.reading());
371	    }
372	
373	    private boolean readingEquals(String left, String right) {
374	        if (left == null || right == null) {
375	            return Objects.equals(left, right);
376	        }
377	        return new BigDecimal(left).compareTo(new BigDecimal(right)) == 0;
378	    }
379	
380	    /**
381	     * 幂等检查：同键同参返回原成功结果；同键异参返回 409；无记录返回 null 继续执行。
382	     */
383	    private WriteOutcome checkReplay(String requestId, String fingerprint) {
384	        Optional<RequestLogEntry> existing = requestLogRepository.find(requestId);
385	        if (existing.isEmpty()) {
386	            return null;
387	        }
388	        RequestLogEntry entry = existing.get();
389	        if (!entry.fingerprint().equals(fingerprint)) {
390	            throw ApiException.conflict("requestId reused with different parameters: " + requestId, null);
391	        }
392	        return new WriteOutcome(entry.responseStatus(), readBody(entry.responseBody()));
393	    }
394	
395	    /**
396	     * 占位写入去重记录；并发同键时主键冲突，等待对方事务结束后读取已提交结果：
397	     * 同参返回重放结果，异参抛 409；正常占位返回 null。业务失败时占位随事务回滚，不占键。
398	     */
399	    private WriteOutcome insertPlaceholder(String requestId, String fingerprint, String operation) {
400	        try {
401	            requestLogRepository.insertPlaceholder(requestId, fingerprint, operation);
402	            return null;
403	        } catch (DuplicateKeyException e) {
404	            RequestLogEntry entry = requestLogRepository.find(requestId)
405	                    .orElseThrow(() -> ApiException.conflict("requestId conflict: " + requestId, null));
406	            if (!entry.fingerprint().equals(fingerprint)) {
407	                throw ApiException.conflict("requestId reused with different parameters: " + requestId, null);
408	            }
409	            return new WriteOutcome(entry.responseStatus(), readBody(entry.responseBody()));
410	        }
411	    }
412	
413	    /**
414	     * 业务成功后回填去重记录响应，并构造本次写操作结果；与业务变更同事务提交。
415	     */
416	    private WriteOutcome complete(String requestId, HttpStatus status, ObservationResponse body) {
417	        requestLogRepository.complete(requestId, status.value(), writeBody(body));
418	        return new WriteOutcome(status.value(), body);
419	    }
420	
421	    private String fingerprint(String operation, String... parts) {
422	        StringBuilder raw = new StringBuilder(operation);
423	        for (String part : parts) {
424	            raw.append(SEPARATOR).append(part == null ? "<null>" : part);
425	        }
426	        try {
427	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
428	            return HexFormat.of().formatHex(digest.digest(raw.toString().getBytes(StandardCharsets.UTF_8)));
429	        } catch (NoSuchAlgorithmException e) {
430	            throw new IllegalStateException("SHA-256 not available", e);
431	        }
432	    }
433	
434	    private String writeBody(ObservationResponse body) {
435	        try {
436	            return objectMapper.writeValueAsString(body);
437	        } catch (JsonProcessingException e) {
438	            throw new IllegalStateException("failed to serialize response", e);
439	        }
440	    }
441	
442	    private ObservationResponse readBody(String json) {
443	        try {
444	            return objectMapper.readValue(json, ObservationResponse.class);
445	        } catch (JsonProcessingException e) {
446	            throw new IllegalStateException("failed to deserialize stored response", e);
447	        }
448	    }
449	
450	    // ---------- 冲突解决辅助逻辑 ----------
451	
452	    /**
453	     * 解析并规范化选择映射：键必须是三个可编辑字段之一，值仅允许 CURRENT/CANDIDATE（大小写不敏感）；
454	     * 重复字段（JSON 反序列化不会出现）或非法键值一律 400。
455	     */
456	    private Map<String, FieldSelection> parseSelections(Map<String, String> raw) {
457	        Map<String, FieldSelection> selections = new LinkedHashMap<>();
458	        for (Map.Entry<String, String> entry : raw.entrySet()) {
459	            String field = entry.getKey() == null ? null : entry.getKey().trim();
460	            if (field == null || !FIELDS.contains(field)) {
461	                throw ApiException.badRequest("selection key must be one of location/reading/note: " + field);
462	            }
463	            FieldSelection selection = FieldSelection.fromValue(entry.getValue());
464	            if (selection == null) {
465	                throw ApiException.badRequest(
466	                        "selection for field '" + field + "' must be CURRENT or CANDIDATE (BASE is not allowed)");
467	            }
468	            if (selections.put(field, selection) != null) {
469	                throw ApiException.badRequest("duplicate selection for field: " + field);
470	            }
471	        }
472	        return selections;
473	    }
474	
475	    /**
476	     * 将选择按固定字段顺序序列化为 JSON 原文，作为指纹与不可变记录的稳定表示。
477	     */
478	    private String writeSelectionsJson(Map<String, FieldSelection> selections) {
479	        Map<String, String> ordered = new LinkedHashMap<>();
480	        for (String field : FIELDS) {
481	            FieldSelection selection = selections.get(field);
482	            if (selection != null) {
483	                ordered.put(field, selection.name());
484	            }
485	        }
486	        try {
487	            return objectMapper.writeValueAsString(ordered);
488	        } catch (JsonProcessingException e) {
489	            throw new IllegalStateException("failed to serialize selections", e);
490	        }
491	    }
492	
493	    /**
494	     * 按原三方规则判断单字段是否冲突：候选未改或任一侧未改或两边改为相同值均不冲突，否则冲突。
495	     */
496	    private boolean fieldConflicts(String base, String current, String candidate, boolean numeric) {
497	        if (valueEquals(candidate, base, numeric)) {
498	            return false;
499	        }
500	        if (valueEquals(current, base, numeric) || valueEquals(candidate, current, numeric)) {
501	            return false;
502	        }
503	        return true;
504	    }
505	
506	    private boolean valueEquals(String left, String right, boolean numeric) {
507	        return numeric ? readingEquals(left, right) : Objects.equals(left, right);
508	    }
509	
510	    /**
511	     * 选择覆盖校验：选择键集合必须恰好等于本次重算出的冲突字段集合。
512	     * 遗漏冲突字段、多选非冲突字段均拒绝（BASE 已在解析阶段拒绝）。
513	     */
514	    private void validateSelectionCoverage(Set<String> selectedFields, List<String> conflictFields) {
515	        Set<String> conflictSet = Set.copyOf(conflictFields);
516	        if (!selectedFields.equals(conflictSet)) {
517	            List<String> missing = new ArrayList<>(conflictFields);
518	            missing.removeAll(selectedFields);
519	            List<String> extra = new ArrayList<>(selectedFields);
520	            extra.removeAll(conflictSet);
521	            List<String> problems = new ArrayList<>();
522	            if (!missing.isEmpty()) {
523	                problems.add("missing selections for conflict fields: " + String.join(", ", missing));
524	            }
525	            if (!extra.isEmpty()) {
526	                problems.add("selections for non-conflict fields are not allowed: " + String.join(", ", extra));
527	            }
528	            throw ApiException.badRequest(
529	                    "selections must cover exactly the recalculated conflict fields; " + String.join("; ", problems)
530	                            + "; current conflict fields: " + String.join(", ", conflictFields));
531	        }
532	    }
533	
534	    /**
535	     * 计算单字段解决结果：冲突字段按人工选择取当前或候选；非冲突字段继续按原三方规则自动合并。
536	     */
537	    private String resolveFieldValue(boolean conflict, FieldSelection selection,
538	                                     String base, String current, String candidate, boolean numeric) {
539	        if (conflict) {
540	            return selection == FieldSelection.CANDIDATE ? candidate : current;
541	        }
542	        if (valueEquals(candidate, base, numeric)) {
543	            return current;
544	        }
545	        return candidate;
546	    }
547	
548	    /**
549	     * 解决请求的 requestId 幂等检查：同键同参返回原成功结果；同键异参返回 409；无记录返回 null。
550	     */
551	    private ResolveOutcome checkResolveReplay(String requestId, String fingerprint) {
552	        Optional<RequestLogEntry> existing = requestLogRepository.find(requestId);
553	        if (existing.isEmpty()) {
554	            return null;
555	        }
556	        RequestLogEntry entry = existing.get();
557	        if (!entry.fingerprint().equals(fingerprint)) {
558	            throw ApiException.conflict("requestId reused with different parameters: " + requestId, null);
559	        }
560	        return new ResolveOutcome(entry.responseStatus(), readResolutionBody(entry.responseBody()));
561	    }
562	
563	    /**
564	     * 解决请求的占位写入，语义与普通写操作一致：冲突后读已提交记录，同参重放、异参 409。
565	     */
566	    private ResolveOutcome insertResolvePlaceholder(String requestId, String fingerprint) {
567	        try {
568	            requestLogRepository.insertPlaceholder(requestId, fingerprint, "RESOLVE");
569	            return null;
570	        } catch (DuplicateKeyException e) {
571	            RequestLogEntry entry = requestLogRepository.find(requestId)
572	                    .orElseThrow(() -> ApiException.conflict("requestId conflict: " + requestId, null));
573	            if (!entry.fingerprint().equals(fingerprint)) {
574	                throw ApiException.conflict("requestId reused with different parameters: " + requestId, null);
575	            }
576	            return new ResolveOutcome(entry.responseStatus(), readResolutionBody(entry.responseBody()));
577	        }
578	    }
579	
580	    /**
581	     * 解决成功后回填去重记录响应，与业务变更、解决记录在同一事务提交。
582	     */
583	    private ResolveOutcome completeResolve(String requestId, HttpStatus status, ResolutionResponse body) {
584	        try {
585	            requestLogRepository.complete(requestId, status.value(), objectMapper.writeValueAsString(body));
586	        } catch (JsonProcessingException e) {
587	            throw new IllegalStateException("failed to serialize resolution response", e);
588	        }
589	        return new ResolveOutcome(status.value(), body);
590	    }
591	
592	    private ResolutionResponse readResolutionBody(String json) {
593	        try {
594	            return objectMapper.readValue(json, ResolutionResponse.class);
595	        } catch (JsonProcessingException e) {
596	            throw new IllegalStateException("failed to deserialize stored resolution response", e);
597	        }
598	    }
599	
600	    /**
601	     * 判断本次请求参数与已存在解决记录是否完全一致（用于 resolutionId 同参重放）。
602	     * expectedCurrentVersion 必须等于记录中的解决前当前版本：任何参数（含乐观锁版本）变化均按改参 409 处理。
603	     */
604	    private boolean sameResolutionParams(ResolutionRecord record, String observationId,
605	                                         ResolveConflictRequest request, String normalizedSelections) {
606	        return Objects.equals(record.observationId(), observationId)
607	                && record.baseVersion() == request.baseVersion()
608	                && record.previousVersion() == request.expectedCurrentVersion()
609	                && Objects.equals(record.candidateLocation(), request.location())
610	                && Objects.equals(record.candidateReading(), request.reading())
611	                && Objects.equals(record.candidateNote(), request.note())
612	                && Objects.equals(record.fieldSelections(), normalizedSelections)
613	                && Objects.equals(record.operator(), request.operator());
614	    }
615	
616	    /**
617	     * 依据已落库的不可变记录重新组装响应（重放路径；指向版本必然已存在）。
618	     */
619	    private ResolutionResponse resolutionResponseOf(ResolutionRecord record) {
620	        ObservationSnapshot pointed = observationRepository.findVersion(
621	                record.observationId(), record.newVersion())
622	                .orElseThrow(() -> new IllegalStateException(
623	                        "pointed version missing for resolution: " + record.resolutionId()));
624	        return ResolutionResponse.of(record, pointed, objectMapper);
625	    }
626	
627	    /**
628	     * 写操作结果：HTTP 状态码与响应体。
629	     */
630	    public record WriteOutcome(int status, ObservationResponse body) {
631	    }
632	
633	    /**
634	     * 冲突解决结果：HTTP 状态码与解决响应体。
635	     */
636	    public record ResolveOutcome(int status, ResolutionResponse body) {
637	    }
638	}
