9	 */
10	public class ApiException extends RuntimeException {
11	
12	    private final HttpStatus status;
13	    private final List<String> conflictFields;
14	    private final Integer currentVersion;
15	
16	    private ApiException(HttpStatus status, String message, List<String> conflictFields, Integer currentVersion) {
17	        super(message);
18	        this.status = status;
19	        this.conflictFields = conflictFields;
20	        this.currentVersion = currentVersion;
21	    }
22	
23	    public HttpStatus status() {
24	        return status;
25	    }
26	
27	    public List<String> conflictFields() {
28	        return conflictFields;
29	    }
30	
31	    public Integer currentVersion() {
32	        return currentVersion;
33	    }
34	
35	    /**
36	     * 400：请求参数不合法（如读数格式错误）。
37	     */
38	    public static ApiException badRequest(String message) {
39	        return new ApiException(HttpStatus.BAD_REQUEST, message, null, null);
40	    }
41	
42	    /**
43	     * 404：观测记录或基线版本不存在。
44	     */
45	    public static ApiException notFound(String message) {
46	        return new ApiException(HttpStatus.NOT_FOUND, message, null, null);
47	    }
48	
49	    /**
50	     * 409：通用冲突（记录已存在、删除版本不匹配、requestId 异参复用）。
51	     */
52	    public static ApiException conflict(String message, Integer currentVersion) {
53	        return new ApiException(HttpStatus.CONFLICT, message, null, currentVersion);
54	    }
55	
56	    /**
57	     * 409：三方合并字段冲突，携带冲突字段与当前版本，不写入任何部分结果。
58	     */
59	    public static ApiException mergeConflict(List<String> conflictFields, int currentVersion) {
60	        return new ApiException(HttpStatus.CONFLICT,
61	                "merge conflict on fields: " + String.join(", ", conflictFields),
62	                List.copyOf(conflictFields), currentVersion);
63	    }
64	
65	    /**
66	     * 410：记录已删除，拒绝新的修改和删除。
67	     */
68	    public static ApiException gone(String message) {
69	        return new ApiException(HttpStatus.GONE, message, null, null);
70	    }
71	}
