210	    @Test
211	    void resolveRecalculatesConflictsAndRejectsStaleSelectionList() throws Exception {
212	        // v1：站点A/备注；v2 服务端同时改地点为站点B、备注为服务端备注
213	        create("req-rc-0", "obs-3", "站点A", "1.0", "备注").andExpect(status().isCreated());
214	        merge("req-rc-1", "obs-3", 1, "站点B", "1.0", "服务端备注").andExpect(status().isOk());
215	        // 离线端基于 v1 改站点C/离线备注：地点、备注双冲突
216	        merge("req-rc-2", "obs-3", 1, "站点C", "1.0", "离线备注")
217	                .andExpect(status().isConflict())
218	                .andExpect(jsonPath("$.conflictFields[0]").value("location"))
219	                .andExpect(jsonPath("$.conflictFields[1]").value("note"));
220	        // 服务端继续前进到 v3：地点改为站点C（与离线端相同），备注保持服务端备注
221	        merge("req-rc-3", "obs-3", 2, "站点C", "1.0", "服务端备注").andExpect(status().isOk());
222	
223	        // 客户端仍按上次看到的双冲突提交：地点已不再冲突，多选非冲突字段，400 且不写入
224	        resolve("req-rc-4", "res-3-bad", "obs-3", 1, 3,
225	                "站点C", "1.0", "离线备注",
226	                Map.of("location", "CANDIDATE", "note", "CANDIDATE"), "op")
227	                .andExpect(status().isBadRequest());
228	        assertThat(versionCount("obs-3")).isEqualTo(3);
229	        assertThat(resolutionCount("obs-3")).isZero();
230	        assertThat(requestLogCount("req-rc-4")).isZero();
231	
232	        // 按服务端重算结果只选择备注：地点自动取相同值站点C，备注接受候选，生成 v4
233	        resolve("req-rc-5", "res-3", "obs-3", 1, 3,
234	                "站点C", "1.0", "离线备注", Map.of("note", "CANDIDATE"), "op")
235	                .andExpect(status().isOk())
236	                .andExpect(jsonPath("$.version").value(4))
237	                .andExpect(jsonPath("$.conflictFields[0]").value("note"))
238	                .andExpect(jsonPath("$.location").value("站点C"))
239	                .andExpect(jsonPath("$.note").value("离线备注"));
240	        assertThat(versionCount("obs-3")).isEqualTo(4);
241	    }
