475	        merge("req-rn2-1", "obs-17", 1, "站点A", "2.5", "备注").andExpect(status().isOk());
476	        // 离线端基于 v1 把读数改为 1.5：与服务端 2.5 冲突
477	        merge("req-rn2-2", "obs-17", 1, "站点A", "1.5", "备注")
478	                .andExpect(status().isConflict())
479	                .andExpect(jsonPath("$.conflictFields[0]").value("reading"));
480	        resolve("req-rn2-3", "res-17", "obs-17", 1, 2,
481	                "站点A", "1.5", "备注", Map.of("reading", "CANDIDATE"), "op")
482	                .andExpect(status().isOk())
483	                .andExpect(jsonPath("$.version").value(3))
484	                .andExpect(jsonPath("$.reading").value("1.5"));
485	
486	        // 候选读数 1.50 与当前 1.5 数值相等：两边改为相同值，无冲突自动接受，结果与当前相同不加版本
487	        resolve("req-rn2-4", "res-17b", "obs-17", 1, 3,
488	                "站点A", "1.50", "备注", Map.of(), "op")
489	                .andExpect(status().isOk())
