491	                .andExpect(jsonPath("$.contentChanged").value(false))
492	                .andExpect(jsonPath("$.reading").value("1.5"));
493	    }
494	
495	    @Test
496	    void resolutionHistoryIsOrderedAndRecordsRemainImmutable() throws Exception {
497	        create("req-rh-0", "obs-18", "站点A", "1.0", "备注").andExpect(status().isCreated());
498	        merge("req-rh-1", "obs-18", 1, "站点B", "1.0", "备注").andExpect(status().isOk());
499	        // 第一次解决：站点B/C 冲突选 CANDIDATE，备注自动合并为离线备注 → v3
500	        resolve("req-rh-2", "res-18a", "obs-18", 1, 2,
501	                "站点C", "1.0", "离线备注", Map.of("location", "CANDIDATE"), "op1")
