503	                .andExpect(jsonPath("$.version").value(3));
504	        // 服务端 v4 改地点为站点D；离线端基于 v3 改地点为站点E
505	        merge("req-rh-3", "obs-18", 3, "站点D", "1.0", "离线备注").andExpect(status().isOk());
506	        resolve("req-rh-4", "res-18b", "obs-18", 3, 4,
