510	
511	        // 历史按解决时刻先后返回；每条记录不可变，始终指向解决时的版本
512	        mockMvc.perform(get("/api/observations/{id}/resolutions", "obs-18"))
513	                .andExpect(status().isOk())
514	                .andExpect(jsonPath("$[0].resolutionId").value("res-18a"))
